-- Guest Hub S1 (25 Nov 2026, Ahmed — DECISIONS.md 2026-11-25 «Guest Hub S1»): Instagram and Messenger direct messages
-- through the Meta app «Armada Guest Hub», and data deletion requests on every channel. Generated by
-- scripts/hub-s1-migration.mjs from scripts/hub-s1-migration.src.sql and the latest definitions of the functions it edits —
-- never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   The Meta channels (provider meta: the Page id / the Instagram account id), the brand unit «السوشيال» (both branches,
--   created OFF — only the system admin switches it on; its audience starts «حسابات التجربة فقط»), the Meta identities
--   (PSID / IGSID → a guest profile with no phone), the conversation's branch on a brand unit, the deletion requests and
--   «حذف بيانات المحادثات». The send context, the staff send (24 hours; 7 days with «Human Agent» once Meta approves it),
--   the held answers, the turn queue (the audience), the claim (the conversation's branch, the licences of the branch
--   units, the channel's kind), the hand-off's branch, the standby of the brand unit, the test lab gate (the two branch
--   units'), the daily report's channel split, the thread, the chat booking's phone (asked on Instagram / Messenger).
-- No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE carries a WHERE.

-- ───────────────────────────────────────────── 1. channels and the social unit ─────────────────────────────────────────────
-- S1 (Ahmed, 25 Nov 2026): Instagram and Messenger direct messages through the Meta app «Armada Guest Hub» (Instagram API
-- with Facebook Login for Business: one Page token sends and receives both). A Meta channel's address is the Page id
-- (messenger) or the Instagram professional account id (instagram); page_id is the Page both are sent through.
alter table public.hub_channels drop constraint hub_channels_provider_check;
alter table public.hub_channels add constraint hub_channels_provider_check check (provider in ('ycloud', 'meta'));
alter table public.hub_channels add column page_id text check (page_id is null or page_id ~ '^[0-9]{5,30}$');
alter table public.hub_channels add constraint hub_channels_meta_address
  check (kind not in ('instagram', 'messenger') or (provider = 'meta' and address ~ '^[0-9]{5,30}$' and page_id is not null));
comment on column public.hub_channels.page_id is 'S1 (25 Nov 2026): the Facebook Page a Meta channel (Messenger, or the Instagram account linked to the Page) is sent through.';

-- the brand unit «السوشيال»: both branches, no branch of its own (the conversation's branch is asked when an answer
-- depends on it); its own audience (test accounts only / everyone / standby), set by the system admin
alter table public.hub_units drop constraint hub_units_kind_check;
alter table public.hub_units add constraint hub_units_kind_check check (kind in ('branch', 'dining', 'brand'));
alter table public.hub_units alter column branch_slug drop not null;
alter table public.hub_units add constraint hub_units_brand_branch check ((kind = 'brand') = (branch_slug is null));
alter table public.hub_units add column social_mode text not null default 'test' check (social_mode in ('test', 'live', 'standby'));
alter table public.hub_units add column social_standby_minutes smallint not null default 5 check (social_standby_minutes between 1 and 30);
-- «Human Agent» (Meta's feature, App Review): staff replies up to 7 days after the guest's last message — off until approved
alter table public.hub_units add column meta_human_agent boolean not null default false;
comment on column public.hub_units.social_mode is 'S1 (25 Nov 2026), the brand unit only: test = the assistant replies only to the accounts marked «حساب تجربة»; live = everyone; standby = everyone, after waiting social_standby_minutes for a staff reply.';

-- the conversation's branch on a brand unit (named by the guest, or picked from «في أي فرع تقصد…؟») and the question
-- that waits for it (topics and intents only — never the guest's words)
alter table public.hub_conversations add column branch_slug text references public.branches (slug) on update cascade;
alter table public.hub_conversations add column branch_pending jsonb check (branch_pending is null or jsonb_typeof(branch_pending) = 'object');

-- ───────────────────────────────────────────── 2. Meta identities ─────────────────────────────────────────────
-- the platform's user id for our Page (PSID) or our Instagram account (IGSID) → one guest profile with no phone
create table public.hub_social_identities (
  id uuid primary key default gen_random_uuid(),
  channel_id uuid not null references public.hub_channels (id) on delete cascade,
  kind text not null check (kind in ('instagram', 'messenger')),
  user_id text not null check (user_id ~ '^[0-9]{5,40}$'),
  guest_profile_id uuid not null references public.guest_profiles (id) on delete cascade,
  -- the display name / username when Meta gives them (guest text: cleared by «حذف بيانات المحادثات»)
  display_name text check (display_name is null or char_length(display_name) <= 120),
  username text check (username is null or char_length(username) <= 60),
  -- «حساب تجربة»: while the unit's social_mode is test, the assistant replies only to these (the system admin marks them)
  tester boolean not null default false,
  tester_set_by uuid references auth.users (id) on delete set null,
  tester_set_at timestamptz,
  last_seen_at timestamptz not null default now(),
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (channel_id, user_id, is_test)
);
comment on table public.hub_social_identities is 'S1 (25 Nov 2026): a Messenger PSID or Instagram IGSID of our Page / account → its guest profile (no phone). Written by the social-inbound function (service role) and «حساب تجربة» (the system admin).';
create trigger hub_social_identities_touch before update on public.hub_social_identities for each row execute function internal.stamp();
create index hub_social_identities_profile on public.hub_social_identities (guest_profile_id);
alter table public.hub_social_identities enable row level security;
revoke all on table public.hub_social_identities from public, anon, authenticated;
grant all on table public.hub_social_identities to service_role;

-- ───────────────────────────────────────────── 3. data deletion requests ─────────────────────────────────────────────
-- S6 (Ahmed, 25 Nov 2026): «احذف بياناتي» / “Delete my data” on any channel, or an email to info@ — one open request per
-- guest; «حذف بيانات المحادثات» (the system admin) removes the conversations' texts and media, keeps bookings and requests
create table public.hub_data_deletions (
  id uuid primary key default gen_random_uuid(),
  guest_profile_id uuid not null references public.guest_profiles (id) on delete cascade,
  conversation_id uuid references public.hub_conversations (id) on delete set null,
  channel_kind text check (channel_kind is null or channel_kind in ('whatsapp', 'instagram', 'messenger')),
  via text not null check (via in ('chat', 'staff')),
  status text not null default 'open' check (status in ('open', 'done')),
  requested_at timestamptz not null default now(),
  emailed_at timestamptz,
  done_at timestamptz,
  done_by uuid references auth.users (id) on delete set null,
  -- numbers only
  cleared jsonb not null default '{}'::jsonb check (jsonb_typeof(cleared) = 'object'),
  notified_at timestamptz,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.hub_data_deletions is 'S6 (25 Nov 2026): data deletion requests «طلبات حذف البيانات» — numbers and times only, never a text.';
create trigger hub_data_deletions_touch before update on public.hub_data_deletions for each row execute function internal.stamp();
create unique index hub_data_deletions_one_open on public.hub_data_deletions (guest_profile_id) where status = 'open';
alter table public.hub_data_deletions enable row level security;
revoke all on table public.hub_data_deletions from public, anon, authenticated;
grant all on table public.hub_data_deletions to service_role;

-- ───────────────────────────────────────────── 4. the social unit ─────────────────────────────────────────────
-- created off (only the system admin switches a unit on, after «ربط الصفحة وحساب انستجرام» verified its channels); the
-- persona and the skills of the Airport Road unit (S1: one assistant for every channel); the admin and management users
-- as its team (it covers both branches)
insert into public.hub_units (key, kind, name_ar, name_en, branch_slug, status, assistant_mode, skills, persona, persona_live, sort)
select 'social', 'brand', 'السوشيال', 'Social', null, 'active', 'off', u.skills, u.persona, u.persona_live, 50
  from public.hub_units u where u.key = 'airport-road'
on conflict (key) do nothing;
insert into public.hub_unit_members (unit_id, staff_id)
select u.id, s.user_id from public.hub_units u join public.staff s on s.active and s.role in ('admin', 'management')
 where u.key = 'social'
on conflict do nothing;

-- ───────────────────────────────────────────── 5. helpers ─────────────────────────────────────────────
-- the profile of a Meta user of this channel (created with no phone on the first message)
create function internal.hub_social_profile(p_channel public.hub_channels, p_user text, p_name text, p_username text, p_test boolean) returns public.guest_profiles
language plpgsql security definer set search_path = '' as $$
declare
  i public.hub_social_identities;
  g public.guest_profiles;
begin
  if coalesce(p_user, '') !~ '^[0-9]{5,40}$' then raise exception 'hub_social_user' using errcode = '22023'; end if;
  select * into i from public.hub_social_identities x where x.channel_id = p_channel.id and x.user_id = p_user and x.is_test = coalesce(p_test, false) for update;
  if i.id is null then
    insert into public.guest_profiles (is_test, wa_profile_name) values (coalesce(p_test, false), p_name) returning * into g;
    insert into public.hub_social_identities (channel_id, kind, user_id, guest_profile_id, display_name, username, is_test)
    values (p_channel.id, p_channel.kind, p_user, g.id, p_name, p_username, coalesce(p_test, false))
    on conflict (channel_id, user_id, is_test) do nothing
    returning * into i;
    if i.id is null then
      -- a second delivery won the race: its profile
      delete from public.guest_profiles where id = g.id;
      select * into i from public.hub_social_identities x where x.channel_id = p_channel.id and x.user_id = p_user and x.is_test = coalesce(p_test, false);
    end if;
  else
    update public.hub_social_identities set display_name = coalesce(p_name, display_name), username = coalesce(p_username, username), last_seen_at = now()
     where id = i.id;
  end if;
  select * into g from public.guest_profiles where id = i.guest_profile_id;
  -- an inbound message counts as activity for the 24-month profile retention (spec §3.5)
  update public.guest_profiles set wa_profile_name = coalesce(p_name, wa_profile_name), last_activity_at = greatest(last_activity_at, now()) where id = g.id
  returning * into g;
  return g;
end;
$$;

-- the Meta user id a conversation sends to (NULL for WhatsApp)
create function internal.hub_social_user(c public.hub_conversations) returns text
language sql stable security definer set search_path = '' as $$
  select i.user_id from public.hub_social_identities i where i.channel_id = c.channel_id and i.guest_profile_id = c.guest_profile_id and i.is_test = c.is_test limit 1
$$;

-- S1: the social unit's audience — test: only «حساب تجربة»; live / standby: everyone. The CHANNEL's unit decides (a
-- conversation handed to a branch's reception keeps its channel's audience)
create function internal.hub_social_may_reply(c public.hub_conversations) returns boolean
language sql stable security definer set search_path = '' as $$
  select case
    when ch.provider <> 'meta' then true
    when cu.social_mode in ('live', 'standby') then true
    else coalesce((select i.tester from public.hub_social_identities i where i.channel_id = c.channel_id and i.guest_profile_id = c.guest_profile_id and i.is_test = c.is_test limit 1), false)
  end
    from public.hub_channels ch join public.hub_units cu on cu.id = ch.unit_id
   where ch.id = c.channel_id
$$;

-- ───────────────────────────────────────────── 6. the webhook path (service role) ─────────────────────────────────────────────
-- p: {kind (instagram | messenger), channel (the Page id or the Instagram account id), user (PSID / IGSID), provider_id (the
-- mid), sent_at, kind_msg, body, payload, media {mime}, name, username, is_test}
create function public.hub_ingest_social(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  ch public.hub_channels;
  g public.guest_profiles;
  c public.hub_conversations;
  v_at timestamptz := coalesce(nullif(p ->> 'sent_at', '')::timestamptz, now());
  v_kind text := coalesce(nullif(p ->> 'kind_msg', ''), 'unsupported');
  v_pid text := nullif(left(p ->> 'provider_id', 200), '');
  v_mid uuid;
  v_name text := nullif(left(btrim(regexp_replace(coalesce(p ->> 'name', ''), '[[:cntrl:]]', ' ', 'g')), 120), '');
  v_user_name text := nullif(left(btrim(regexp_replace(coalesce(p ->> 'username', ''), '[[:cntrl:]]', ' ', 'g')), 60), '');
begin
  if not internal.hub_setting_bool('hub_inbox_on') then return jsonb_build_object('stored', false, 'reason', 'inbox_off'); end if;
  perform set_config('app.actor', 'meta', true);
  if v_pid is null then return jsonb_build_object('stored', false, 'reason', 'no_id'); end if;
  if v_at > now() + interval '5 minutes' then v_at := now(); end if;
  select * into ch from public.hub_channels x where x.provider = 'meta' and x.kind = p ->> 'kind' and x.address = p ->> 'channel';
  if ch.id is null then return jsonb_build_object('stored', false, 'reason', 'unknown_channel'); end if;
  if exists (select 1 from public.hub_messages m where m.channel_id = ch.id and m.provider_message_id = v_pid) then
    return jsonb_build_object('stored', false, 'reason', 'duplicate');
  end if;
  if v_kind not in ('text', 'interactive', 'button_reply', 'image', 'audio', 'video', 'document', 'location', 'sticker', 'reaction') then v_kind := 'unsupported'; end if;
  g := internal.hub_social_profile(ch, p ->> 'user', v_name, v_user_name, v_test);
  c := internal.hub_conversation_for(ch, g.id, v_test, null);
  begin
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, provider_message_id, idempotency_key, status, sent_at,
                                     media_mime, is_test)
    values (c.id, ch.id, 'in', 'guest', v_kind, nullif(left(p ->> 'body', 8000), ''),
            case when jsonb_typeof(p -> 'payload') = 'object' then p -> 'payload' else '{}'::jsonb end,
            v_pid, 'in:' || ch.id || ':' || v_pid, 'received', v_at, nullif(left(p -> 'media' ->> 'mime', 120), ''), v_test)
    returning id into v_mid;
  exception when unique_violation then
    return jsonb_build_object('stored', false, 'reason', 'duplicate');
  end;
  update public.hub_conversations
     set last_guest_at = greatest(coalesce(last_guest_at, v_at), v_at),
         window_expires_at = greatest(coalesce(window_expires_at, v_at + interval '24 hours'), v_at + interval '24 hours'),
         waiting_since = coalesce(waiting_since, v_at)
   where id = c.id;
  return jsonb_build_object('stored', true, 'conversation_id', c.id, 'message_id', v_mid, 'unit', (select u.key from public.hub_units u where u.id = ch.unit_id),
                            'profile_id', g.id, 'may_reply', internal.hub_social_may_reply(c),
                            'media_wanted', v_kind in ('image', 'audio', 'video', 'document', 'sticker') and coalesce(p -> 'media' ->> 'url', '') <> '');
end;
$$;

-- a message sent from Meta Business Suite or the Instagram app (an echo without our app id): a staff reply — the
-- conversation goes to staff, owner «الجوال» (T23, as the WhatsApp Business app's echo). p: {kind, channel, user,
-- provider_id, sent_at, kind_msg, body, is_test}
create function public.hub_ingest_social_echo(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  ch public.hub_channels;
  g public.guest_profiles;
  c public.hub_conversations;
  v_at timestamptz := coalesce(nullif(p ->> 'sent_at', '')::timestamptz, now());
  v_kind text := coalesce(nullif(p ->> 'kind_msg', ''), 'unsupported');
  v_pid text := nullif(left(p ->> 'provider_id', 200), '');
  v_mid uuid;
begin
  if not internal.hub_setting_bool('hub_inbox_on') then return jsonb_build_object('stored', false, 'reason', 'inbox_off'); end if;
  perform set_config('app.actor', 'meta', true);
  if v_pid is null then return jsonb_build_object('stored', false, 'reason', 'no_id'); end if;
  if v_at > now() + interval '5 minutes' then v_at := now(); end if;
  select * into ch from public.hub_channels x where x.provider = 'meta' and x.kind = p ->> 'kind' and x.address = p ->> 'channel';
  if ch.id is null then return jsonb_build_object('stored', false, 'reason', 'unknown_channel'); end if;
  -- our own send echoed back (the id we recorded) is never a staff reply
  if exists (select 1 from public.hub_messages m where m.channel_id = ch.id and m.provider_message_id = v_pid) then
    return jsonb_build_object('stored', false, 'reason', 'duplicate');
  end if;
  if v_kind not in ('text', 'interactive', 'image', 'audio', 'video', 'document', 'sticker', 'template') then v_kind := 'unsupported'; end if;
  g := internal.hub_social_profile(ch, p ->> 'user', null, null, v_test);
  c := internal.hub_conversation_for(ch, g.id, v_test, null);
  begin
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, provider_message_id, idempotency_key, status, sent_at, is_test)
    values (c.id, ch.id, 'out', 'phone', v_kind, nullif(left(p ->> 'body', 8000), ''), jsonb_build_object('source', 'meta_app'),
            v_pid, 'echo:' || ch.id || ':' || v_pid, 'sent', v_at, v_test)
    returning id into v_mid;
  exception when unique_violation then
    return jsonb_build_object('stored', false, 'reason', 'duplicate');
  end;
  if c.state <> 'human' then
    insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
    values (c.id, 'handoff', c.state, 'human', 'phone_reply', c.is_test);
  end if;
  if c.owner_kind is distinct from 'phone' then
    insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
    values (c.id, 'owner', c.owner_kind, 'phone', 'phone_reply', c.is_test);
  end if;
  update public.hub_conversations
     set state_before_human = case when state <> 'human' and state in ('new', 'inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then state else state_before_human end,
         state_changed_at = case when state <> 'human' then now() else state_changed_at end,
         human_reason = case when state <> 'human' then 'phone_reply' else human_reason end,
         state = 'human', owner_kind = 'phone', owner_staff_id = null,
         last_staff_at = greatest(coalesce(last_staff_at, v_at), v_at),
         first_response_at = coalesce(first_response_at, case when waiting_since is not null then v_at end),
         waiting_since = null
   where id = c.id;
  return jsonb_build_object('stored', true, 'conversation_id', c.id, 'message_id', v_mid);
end;
$$;

-- delivery / read: forward only. p: {kind, channel, user, mids (delivered), watermark (read up to, epoch ms), status}
create function public.hub_social_status(p jsonb) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  n integer := 0;
  v_mids text[] := array(select jsonb_array_elements_text(coalesce(p -> 'mids', '[]'::jsonb)));
  v_mark timestamptz := case when coalesce(p ->> 'watermark', '') ~ '^[0-9]{10,16}$' then to_timestamp((p ->> 'watermark')::numeric / 1000.0) end;
begin
  select * into ch from public.hub_channels x where x.provider = 'meta' and x.kind = p ->> 'kind' and x.address = p ->> 'channel';
  if ch.id is null then return 0; end if;
  if p ->> 'status' = 'delivered' and cardinality(v_mids) > 0 then
    update public.hub_messages set status = 'delivered'
     where channel_id = ch.id and direction = 'out' and provider_message_id = any (v_mids) and status in ('accepted', 'sent');
    get diagnostics n = row_count;
  elsif p ->> 'status' = 'read' and (v_mark is not null or cardinality(v_mids) > 0) then
    update public.hub_messages m set status = 'read'
      from public.hub_conversations c join public.hub_social_identities i on i.channel_id = c.channel_id and i.guest_profile_id = c.guest_profile_id and i.is_test = c.is_test
     where m.conversation_id = c.id and m.channel_id = ch.id and i.user_id = p ->> 'user' and m.direction = 'out' and m.status in ('accepted', 'sent', 'delivered')
       and (m.provider_message_id = any (v_mids) or (v_mark is not null and m.sent_at <= v_mark + interval '1 second'));
    get diagnostics n = row_count;
  end if;
  return n;
end;
$$;

-- the conversation's branch on a brand unit (the engine read it from the guest, or the guest picked it), and the question
-- waiting for it (topics and intents only). p_clear_pending: the waiting question was answered
create function public.hub_social_branch_set(p_conversation uuid, p_branch text, p_pending jsonb, p_clear_pending boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if p_branch is not null and p_branch not in ('airport-road', 'shafa-road') then raise exception 'hub_branch' using errcode = '22023'; end if;
  update public.hub_conversations c
     set branch_slug = coalesce(p_branch, c.branch_slug),
         branch_pending = case when p_clear_pending then null when p_pending is not null and jsonb_typeof(p_pending) = 'object' then p_pending else c.branch_pending end
   where c.id = p_conversation and exists (select 1 from public.hub_units u where u.id = c.unit_id and u.kind = 'brand');
end;
$$;

-- «ربط الصفحة وحساب انستجرام» (hub-admin meta_setup, after the Graph API subscriptions succeeded): the two Meta channels of
-- the social unit, connected and verified. p: {page_id, page_name, ig_id, ig_username}
create function public.hub_social_channels_store(p jsonb, p_actor uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_page text := p ->> 'page_id';
  v_ig text := nullif(p ->> 'ig_id', '');
  v_out jsonb := '[]'::jsonb;
  r record;
begin
  if coalesce(v_page, '') !~ '^[0-9]{5,30}$' or (v_ig is not null and v_ig !~ '^[0-9]{5,30}$') then raise exception 'hub_meta_ids' using errcode = '22023'; end if;
  select * into u from public.hub_units where key = 'social';
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  perform set_config('app.actor', 'meta', true);
  for r in select * from (values ('messenger', v_page, left(p ->> 'page_name', 120)), ('instagram', v_ig, left(nullif(p ->> 'ig_username', ''), 120))) as x(kind, address, name)
            where x.address is not null loop
    insert into public.hub_channels (unit_id, provider, kind, address, page_id, display_name, connected, verified_at, provider_status)
    values (u.id, 'meta', r.kind, r.address, v_page, r.name, true, now(), 'subscribed')
    on conflict (kind, address) do update set page_id = excluded.page_id, display_name = coalesce(excluded.display_name, public.hub_channels.display_name),
                                               connected = true, verified_at = now(), provider_status = 'subscribed', unit_id = excluded.unit_id;
    v_out := v_out || jsonb_build_object('kind', r.kind, 'address', r.address);
  end loop;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (p_actor, case when p_actor is null then 'meta' end, 'hub_channels', 'social', null, 'update', null, jsonb_build_object('channels', v_out), gen_random_uuid());
  return jsonb_build_object('ok', true, 'channels', v_out);
end;
$$;

-- ───────────────────────────────────────────── 7. data deletion ─────────────────────────────────────────────
-- the request (service role: the router, on «احذف بياناتي»): one open request per guest. p: {conversation, phone, kind, is_test}
create function public.hub_data_delete_request(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  v_id uuid;
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  if nullif(p ->> 'conversation', '') is not null then
    select * into c from public.hub_conversations where id = (p ->> 'conversation')::uuid;
    select * into g from public.guest_profiles where id = c.guest_profile_id;
  elsif coalesce(p ->> 'phone', '') ~ '^\+[1-9][0-9]{7,14}$' then
    g := internal.hub_profile_for(p ->> 'phone', v_test);
  end if;
  if g.id is null then return jsonb_build_object('created', false, 'reason', 'no_guest'); end if;
  select d.id into v_id from public.hub_data_deletions d where d.guest_profile_id = g.id and d.status = 'open';
  if v_id is not null then return jsonb_build_object('created', false, 'request_id', v_id, 'reason', 'open'); end if;
  insert into public.hub_data_deletions (guest_profile_id, conversation_id, channel_kind, via, is_test)
  values (g.id, c.id, case when p ->> 'kind' in ('whatsapp', 'instagram', 'messenger') then p ->> 'kind' end, 'chat', coalesce(c.is_test, v_test))
  on conflict (guest_profile_id) where status = 'open' do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('created', false, 'reason', 'open'); end if;
  if c.id is not null then
    insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
    values (c.id, 'state', c.state, c.state, 'data_delete_request', c.is_test);
  end if;
  return jsonb_build_object('created', true, 'request_id', v_id,
    'recipients', to_jsonb(array(select u.email from public.staff s join auth.users u on u.id = s.user_id where s.active and s.role = 'admin' and u.email is not null order by u.email)));
end;
$$;
create function public.hub_data_delete_emailed(p_request uuid) returns void
language sql security definer set search_path = '' as $$
  update public.hub_data_deletions set emailed_at = coalesce(emailed_at, now()) where id = p_request;
$$;

-- «حذف بيانات المحادثات» (the system admin, on a guest of «المحادثات» or a request of «طلبات حذف البيانات»): every
-- conversation of the guest on every channel — the texts, translations, transcripts, the understanding, the drafts'
-- fields, the queue's excerpts, the alert lines; the media marked for deletion (wa-automation hub-media-purge). Bookings,
-- partner requests and the conversations' times, kinds and statuses are kept. One audit row of counts. p_done_text: the
-- line «تم حذف بيانات محادثاتك معنا.» in each language — queued in the guest's latest conversation when its window is open
create function public.hub_data_delete(p_profile uuid, p_done_text jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  g public.guest_profiles;
  c public.hub_conversations;
  v_conv uuid[];
  v_msgs integer;
  v_media integer;
  v_turns integer;
  v_drafts integer;
  v_excerpts integer;
  v_batch uuid := gen_random_uuid();
  v_lang text;
  v_body text;
  v_id uuid;
  ctx jsonb;
  v_notify jsonb;
  v_url text := internal.vault_value('job_sweep_url');
  v_token text := internal.vault_value('wa_cron_token');
  v_req bigint;
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = p_profile;
  if g.id is null then raise exception 'hub_guest' using errcode = '22023'; end if;
  v_conv := array(select x.id from public.hub_conversations x where x.guest_profile_id = g.id);
  update public.hub_messages set media_pending_delete = true where conversation_id = any (v_conv) and media_path is not null and not media_pending_delete;
  get diagnostics v_media = row_count;
  update public.hub_messages set body = null, translation_ar = null, translation_en = null, transcript = null, purged_at = coalesce(purged_at, now())
   where conversation_id = any (v_conv) and (body is not null or translation_ar is not null or translation_en is not null or transcript is not null);
  get diagnostics v_msgs = row_count;
  update public.hub_turns set understanding = null, purged_at = now() where conversation_id = any (v_conv) and understanding is not null;
  get diagnostics v_turns = row_count;
  update public.hub_drafts set fields = '{}'::jsonb, purged_at = now() where conversation_id = any (v_conv) and fields <> '{}'::jsonb;
  get diagnostics v_drafts = row_count;
  update public.hub_unanswered set question_excerpt = null where conversation_id = any (v_conv) and question_excerpt is not null;
  get diagnostics v_excerpts = row_count;
  update public.hub_handoffs set summary = null where conversation_id = any (v_conv) and summary is not null;
  update public.hub_conversations set branch_pending = null where id = any (v_conv) and branch_pending is not null;
  update public.hub_social_identities set display_name = null, username = null where guest_profile_id = g.id and (display_name is not null or username is not null);
  update public.guest_profiles set wa_profile_name = null where id = g.id and wa_profile_name is not null;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), null, 'hub_data_delete', g.id::text, null, 'update', null,
          jsonb_build_object('conversations', cardinality(v_conv), 'messages', v_msgs, 'media', v_media, 'turns', v_turns, 'drafts', v_drafts, 'excerpts', v_excerpts), v_batch);
  update public.hub_data_deletions
     set status = 'done', done_at = now(), done_by = auth.uid(),
         cleared = jsonb_build_object('conversations', cardinality(v_conv), 'messages', v_msgs, 'media', v_media)
   where guest_profile_id = g.id and status = 'open';
  if not found then
    insert into public.hub_data_deletions (guest_profile_id, via, status, done_at, done_by, cleared, is_test)
    values (g.id, 'staff', 'done', now(), auth.uid(), jsonb_build_object('conversations', cardinality(v_conv), 'messages', v_msgs, 'media', v_media), g.is_test);
  end if;
  -- the line to the guest, in the latest conversation whose window is open (never a template; nothing when closed)
  select * into c from public.hub_conversations x where x.guest_profile_id = g.id and x.window_expires_at > now() order by x.last_guest_at desc nulls last limit 1;
  if c.id is not null and p_done_text is not null then
    v_lang := case when coalesce(c.language, g.language) = 'en' then 'en' else 'ar' end;
    v_body := nullif(btrim(coalesce(p_done_text ->> v_lang, '')), '');
    if v_body is not null then
      begin
        ctx := internal.hub_send_context(c);
        insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, sent_at, language, is_test)
        values (c.id, c.channel_id, 'out', 'system', 'text', v_body, jsonb_build_object('data_delete', true), 'delete:' || v_batch, 'queued', now(), v_lang, c.is_test)
        returning id into v_id;
        v_notify := jsonb_build_object('id', v_id, 'body', v_body) || ctx;
        update public.hub_data_deletions set notified_at = now() where guest_profile_id = g.id and done_at is not null and notified_at is null;
      exception when others then
        v_notify := null;
      end;
    end if;
  end if;
  if v_media > 0 and coalesce(v_url, '') <> '' and coalesce(v_token, '') <> '' and v_url ~ '/functions/v1/' then
    v_req := net.http_post(
      url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/wa-automation'),
      body := jsonb_build_object('action', 'hub-media-purge'),
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-cron', v_token),
      timeout_milliseconds := 60000);
  end if;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'conversations', cardinality(v_conv), 'messages', v_msgs, 'media', v_media, 'notify', v_notify);
end;
$$;

-- «طلبات حذف البيانات» (the system admin): the requests — open first; numbers and times, the guest's label and channel
create function public.hub_data_deletions_list() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'profile_id', d.guest_profile_id, 'conversation_id', d.conversation_id, 'channel_kind', d.channel_kind,
                                                       'via', d.via, 'status', d.status, 'requested_at', d.requested_at, 'done_at', d.done_at,
                                                       'done_by_name', internal.staff_name(d.done_by), 'cleared', d.cleared, 'notified_at', d.notified_at,
                                                       'label', internal.hub_guest_label(g), 'is_test', d.is_test)
                                    order by (d.status = 'open') desc, d.requested_at desc), '[]'::jsonb)
            from (select * from public.hub_data_deletions x order by (x.status = 'open') desc, x.requested_at desc limit 100) d
            join public.guest_profiles g on g.id = d.guest_profile_id);
end;
$$;

-- ───────────────────────────────────────────── 8. «السوشيال» in «إعدادات المساعد» ─────────────────────────────────────────────
create function public.hub_social_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  if not (internal.can('assistant', 'view') and internal.can_branch(null)) then raise exception 'hub_forbidden' using errcode = '42501'; end if;
  select * into u from public.hub_units where key = 'social';
  if u.id is null then return jsonb_build_object('unit', null); end if;
  return jsonb_build_object(
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'name_ar', u.name_ar, 'mode', u.assistant_mode, 'social_mode', u.social_mode,
                               'standby_minutes', u.social_standby_minutes, 'human_agent', u.meta_human_agent, 'status', u.status),
    'channels', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'address', c.address, 'display_name', c.display_name, 'connected', c.connected,
                                                         'verified_at', c.verified_at, 'sending_enabled', c.sending_enabled) order by c.kind), '[]'::jsonb)
                   from public.hub_channels c where c.unit_id = u.id),
    'accounts', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'name', i.display_name, 'username', i.username, 'tester', i.tester,
                                                         'last_seen_at', i.last_seen_at, 'tester_set_at', i.tester_set_at) order by i.tester desc, i.last_seen_at desc), '[]'::jsonb)
                   from (select * from public.hub_social_identities x where not x.is_test order by x.tester desc, x.last_seen_at desc limit 30) i),
    'system_admin', internal.is_system_admin());
end;
$$;

-- the system admin: the audience, the standby minutes, «Human Agent» (only once Meta approved it). Returns the row before
-- («تراجع» saves it back)
create function public.hub_social_save(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_old jsonb;
  v_batch uuid := gen_random_uuid();
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into u from public.hub_units where key = 'social' for update;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if coalesce(p ->> 'social_mode', u.social_mode) not in ('test', 'live', 'standby')
     or coalesce(p ->> 'standby_minutes', u.social_standby_minutes::text) !~ '^([1-9]|[12][0-9]|30)$' then
    raise exception 'hub_social_value' using errcode = '22023';
  end if;
  v_old := jsonb_build_object('social_mode', u.social_mode, 'standby_minutes', u.social_standby_minutes, 'human_agent', u.meta_human_agent);
  update public.hub_units
     set social_mode = coalesce(p ->> 'social_mode', social_mode),
         social_standby_minutes = coalesce((p ->> 'standby_minutes')::smallint, social_standby_minutes),
         meta_human_agent = coalesce((p ->> 'human_agent')::boolean, meta_human_agent)
   where id = u.id;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), null, 'hub_units', u.key, null, 'update', v_old,
          (select jsonb_build_object('social_mode', x.social_mode, 'standby_minutes', x.social_standby_minutes, 'human_agent', x.meta_human_agent) from public.hub_units x where x.id = u.id), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', v_old);
end;
$$;

-- «حساب تجربة» on a Meta account (the system admin)
create function public.hub_social_tester_set(p_identity uuid, p_on boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  i public.hub_social_identities;
  v_batch uuid := gen_random_uuid();
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into i from public.hub_social_identities where id = p_identity for update;
  if i.id is null or p_on is null then raise exception 'hub_social_identity' using errcode = '22023'; end if;
  update public.hub_social_identities set tester = p_on, tester_set_by = auth.uid(), tester_set_at = now() where id = i.id;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), null, 'hub_social_identities', i.id::text, null, 'update', jsonb_build_object('tester', i.tester), jsonb_build_object('tester', p_on), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', i.tester);
end;
$$;

revoke execute on function internal.hub_social_profile(public.hub_channels, text, text, text, boolean), internal.hub_social_user(public.hub_conversations),
  internal.hub_social_may_reply(public.hub_conversations) from public, anon, authenticated;
revoke execute on function public.hub_ingest_social(jsonb), public.hub_ingest_social_echo(jsonb), public.hub_social_status(jsonb),
  public.hub_social_branch_set(uuid, text, jsonb, boolean), public.hub_social_channels_store(jsonb, uuid), public.hub_data_delete_request(jsonb),
  public.hub_data_delete_emailed(uuid) from public, anon, authenticated;
grant execute on function public.hub_ingest_social(jsonb), public.hub_ingest_social_echo(jsonb), public.hub_social_status(jsonb),
  public.hub_social_branch_set(uuid, text, jsonb, boolean), public.hub_social_channels_store(jsonb, uuid), public.hub_data_delete_request(jsonb),
  public.hub_data_delete_emailed(uuid) to service_role;
revoke execute on function public.hub_data_delete(uuid, jsonb), public.hub_data_deletions_list(), public.hub_social_overview(), public.hub_social_save(jsonb),
  public.hub_social_tester_set(uuid, boolean) from public, anon;
grant execute on function public.hub_data_delete(uuid, jsonb), public.hub_data_deletions_list(), public.hub_social_overview(), public.hub_social_save(jsonb),
  public.hub_social_tester_set(uuid, boolean) to authenticated, service_role;

-- ───────────────────────────────────────────── 9. the functions S1 edits ─────────────────────────────────────────────

create or replace function internal.hub_send_context(c public.hub_conversations) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  g public.guest_profiles;
  u public.hub_units;
  v_typing text;
  v_user text;
begin
  if not internal.hub_setting_bool('hub_inbox_on') then raise exception 'hub_inbox_off' using errcode = 'P0001'; end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  if not ch.sending_enabled then raise exception 'hub_sending_off' using errcode = 'P0001'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then raise exception 'hub_blocked' using errcode = 'P0001'; end if;
  -- S1 (25 Nov 2026): a Meta channel sends to the guest's PSID / IGSID, never a phone
  if ch.provider = 'meta' then
    v_user := internal.hub_social_user(c);
    if v_user is null then raise exception 'hub_no_recipient' using errcode = 'P0001'; end if;
  elsif coalesce(g.phone, '') !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'hub_no_phone' using errcode = 'P0001';
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  -- the guest's last message: YCloud's typing indicator marks it read just before a reply (spec §6.2)
  select m.provider_message_id into v_typing from public.hub_messages m
   where m.conversation_id = c.id and m.direction = 'in' and m.provider_message_id is not null order by m.sent_at desc limit 1;
  return jsonb_build_object('from', ch.address, 'to', coalesce(v_user, g.phone), 'provider', ch.provider, 'kind', ch.kind, 'page_id', ch.page_id,
                            'window_expires_at', c.window_expires_at, 'test', c.is_test,
                            -- «Human Agent» (Meta's feature, once approved): staff text up to 7 days after the guest's last message
                            'human_agent_until', case when ch.provider = 'meta' and (select x.meta_human_agent from public.hub_units x where x.id = ch.unit_id)
                                                      then c.last_guest_at + interval '7 days' end,
                            'typing_id', case when c.window_expires_at > now() then v_typing end,
                            'unit', jsonb_build_object('key', u.key, 'kind', u.kind, 'branch', u.branch_slug,
                                                       'venue_ar', (select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id),
                                                       'venue_en', (select v.name_en from public.dining_venues v where v.id = u.dining_venue_id)));
end;
$$;

create or replace function public.hub_send_begin(p_conversation uuid, p_mode text, p_body text, p_key uuid, p_language text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  ctx jsonb;
  v_body text := btrim(coalesce(p_body, ''));
  v_open boolean;
  v_lang text;
  v_out jsonb := '[]'::jsonb;
  v_id uuid;
  v_key text;
  v_agent boolean;
  v_max integer;
begin
  c := internal.hub_conv_edit(p_conversation);
  if p_key is null or p_mode is null or p_mode not in ('text', 'template', 'held') then raise exception 'hub_send' using errcode = '22023'; end if;
  v_key := 'staff:' || p_key::text;
  -- the same press again: what it stored, nothing sent twice
  if exists (select 1 from public.hub_messages m where m.idempotency_key like v_key || '%') then
    select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'status', m.status, 'send', false) order by m.created_at), '[]') into v_out
      from public.hub_messages m where m.idempotency_key like v_key || '%' and m.conversation_id = c.id;
    return jsonb_build_object('ok', true, 'existing', true, 'messages', v_out);
  end if;
  if c.state = 'closed' then raise exception 'hub_closed' using errcode = 'P0001'; end if;
  ctx := internal.hub_send_context(c);
  v_open := c.window_expires_at is not null and c.window_expires_at > now();
  -- S1: a Meta channel after the 24 hours — staff text only with «Human Agent» (7 days), tagged HUMAN_AGENT
  v_agent := not v_open and nullif(ctx ->> 'human_agent_until', '') is not null and (ctx ->> 'human_agent_until')::timestamptz > now();
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if p_mode = 'text' then
    if not (v_open or v_agent) then raise exception 'hub_window_closed' using errcode = 'P0001'; end if;
    -- (the limit in a variable: the CLI's statement splitter breaks on «if … case … end then» — DECISIONS.md 2026-11-09)
    v_max := case when ctx ->> 'provider' = 'meta' then 1000 else 4096 end;
    if char_length(v_body) not between 1 and v_max then raise exception 'hub_body' using errcode = '22023'; end if;
    insert into public.hub_messages (conversation_id, channel_id, direction, author, staff_id, kind, body, payload, idempotency_key, status, sent_at, is_test)
    values (c.id, c.channel_id, 'out', 'staff', auth.uid(), 'text', v_body, case when v_agent then '{"tag": "HUMAN_AGENT"}'::jsonb else '{}'::jsonb end, v_key, 'queued', now(), c.is_test)
    returning id into v_id;
    v_out := v_out || jsonb_build_object('id', v_id, 'kind', 'text', 'body', v_body, 'send', true, 'tag', case when v_agent then 'HUMAN_AGENT' end);
  else
    if p_mode = 'held' then
      if v_open then raise exception 'hub_window_open' using errcode = 'P0001'; end if;
      if char_length(v_body) not between 1 and 4096 then raise exception 'hub_body' using errcode = '22023'; end if;
      insert into public.hub_messages (conversation_id, channel_id, direction, author, staff_id, kind, body, idempotency_key, status, sent_at, is_test)
      values (c.id, c.channel_id, 'out', 'staff', auth.uid(), 'text', v_body, v_key || ':held', 'held', now(), c.is_test)
      returning id into v_id;
      v_out := v_out || jsonb_build_object('id', v_id, 'kind', 'text', 'status', 'held', 'send', false);
    end if;
    -- S1: Meta has no «hub_reply_ready»: a held answer waits for the guest's next message; a template is refused
    if ctx ->> 'provider' = 'meta' then
      if p_mode = 'template' then raise exception 'hub_template_not_approved' using errcode = 'P0001'; end if;
    else
    v_lang := coalesce(nullif(p_language, ''), c.language, g.language, 'ar');
    if v_lang not in ('ar', 'en') then v_lang := 'ar'; end if;
    if not exists (select 1 from public.hub_templates t where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.language = v_lang and t.status = 'APPROVED') then
      raise exception 'hub_template_not_approved' using errcode = 'P0001';
    end if;
    insert into public.hub_messages (conversation_id, channel_id, direction, author, staff_id, kind, body, payload, language, idempotency_key, status, sent_at, is_test)
    values (c.id, c.channel_id, 'out', 'staff', auth.uid(), 'template', null, jsonb_build_object('template', 'hub_reply_ready'), v_lang, v_key || ':template', 'queued', now(), c.is_test)
    returning id into v_id;
    v_out := v_out || jsonb_build_object('id', v_id, 'kind', 'template', 'template', 'hub_reply_ready', 'language', v_lang, 'send', true);
    end if;
  end if;
  perform internal.hub_to_staff(c, auth.uid(), 'staff_reply');
  return jsonb_build_object('ok', true, 'messages', v_out) || ctx;
end;
$$;

create or replace function public.hub_held_claim(p_conversation uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  ch public.hub_channels;
  g public.guest_profiles;
  v_out jsonb;
  v_why text;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.status = 'held') then
    return jsonb_build_object('ok', true, 'messages', '[]'::jsonb);
  end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  v_why := case when c.state = 'closed' then 'closed' when not ch.sending_enabled then 'sending_off' when g.hub_blocked_at is not null then 'blocked'
                when not (c.window_expires_at > now()) then 'window_closed' end;
  if v_why is not null then
    update public.hub_messages set status = 'failed', error_code = v_why where conversation_id = c.id and status = 'held';
    return jsonb_build_object('ok', true, 'messages', '[]'::jsonb, 'reason', v_why);
  end if;
  with x as (update public.hub_messages set status = 'queued' where conversation_id = c.id and status = 'held' returning id, body, created_at)
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'body', x.body) order by x.created_at), '[]') into v_out from x;
  return jsonb_build_object('ok', true, 'messages', v_out, 'from', ch.address, 'to', coalesce(internal.hub_social_user(c), g.phone),
                            'provider', ch.provider, 'kind', ch.kind, 'page_id', ch.page_id, 'window_expires_at', c.window_expires_at, 'test', c.is_test);
end;
$$;

create or replace function public.hub_turn_queue(p_conversation uuid, p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  g public.guest_profiles;
  st jsonb;
  v_turn uuid;
  v_due timestamptz;
  v_kind text;
  -- at most 3 seconds (Ahmed, 15 Nov 2026 — the wait was the largest part of a reply's time)
  v_burst integer := least(greatest(internal.hub_setting_int('hub_burst_ms', 2000), 0), 3000);
  v_test_mode boolean;
  -- «وضع الاستعداد» (16 Nov 2026)
  v_wait integer;
  v_tap boolean;
  v_until timestamptz;
  v_woke boolean;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or c.state = 'closed' then return jsonb_build_object('queued', false, 'reason', 'closed'); end if;
  if not exists (select 1 from public.hub_messages m where m.id = p_message and m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest') then
    return jsonb_build_object('queued', false, 'reason', 'not_guest');
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then return jsonb_build_object('queued', false, 'reason', 'blocked'); end if;
  -- S1 (25 Nov 2026): the social unit in «حسابات التجربة فقط» — an account not marked «حساب تجربة» gets no reply from the
  -- assistant; the team sees it (a staff alert, as every hand-off)
  if not internal.hub_social_may_reply(c) then
    perform internal.hub_to_team(c, 'social_not_tester');
    return jsonb_build_object('queued', false, 'reason', 'not_tester');
  end if;
  st := internal.hub_assistant_state(u);
  if not (st ->> 'active')::boolean then
    perform internal.hub_to_team(c, case when st ->> 'reason' = 'unit_off' then 'assistant_off' else st ->> 'reason' end);
    return jsonb_build_object('queued', false, 'reason', st ->> 'reason');
  end if;
  v_test_mode := st ->> 'mode' = 'test';
  -- the try while the API credit is exhausted (at most every 30 minutes): reserved here
  if (st ->> 'credit_try')::boolean then
    update public.hub_alerts set payload = payload || jsonb_build_object('last_try_at', now()) where kind = 'api_credit' and acknowledged_at is null and not is_test;
  end if;
  if v_test_mode then
    -- a conversation that existed before «تجربة»: its run starts now
    if c.test_state is null then
      update public.hub_conversations set test_state = 'new' where id = c.id;
      c.test_state := 'new';
    end if;
    -- H6c: «بانتظار موظف» (a hand-off with no staff reply yet) is answered by the assistant in a test run as well
    v_kind := case when c.test_state = 'closed' then 'tag' else 'reply' end;
  else
    -- H6c: «بانتظار موظف» → the assistant keeps answering what it can; «مع موظف» → silent (tagging) until the branch's
    -- «عودة المساعد» minutes of staff silence, then the guest's message resumes it
    -- H10: a tap on the alternatives offer («اعرض البدائل» / «لا، شكرًا») is answered whoever holds the conversation
    v_kind := case when c.state = 'human' and internal.hub_human_phase(c, u) is null
                    and not exists (select 1 from public.hub_messages m where m.id = p_message and coalesce(m.payload ->> 'button_id', '') like 'hubx:%')
                   then 'tag' else 'reply' end;
  end if;
  v_tap := exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id'));
  v_woke := v_tap and exists (select 1 from public.hub_turns x where x.conversation_id = c.id and x.status = 'pending' and x.standby_until > now() and x.standby_outcome is null);
  -- a pending turn of this conversation takes the message (the burst; a wait of «وضع الاستعداد» takes every message until it
  -- ends — one reply to all of them); a tap on our own button ends the wait at once
  update public.hub_turns set inbound_message_ids = case when p_message = any (inbound_message_ids) then inbound_message_ids else inbound_message_ids || p_message end,
         due_at = case when v_tap and standby_until > now() and standby_outcome is null then least(due_at, now() + make_interval(secs => v_burst / 1000.0)) else due_at end,
         standby_until = case when v_tap and standby_until > now() and standby_outcome is null then now() else standby_until end
   where conversation_id = c.id and status = 'pending'
  returning id, due_at, standby_until into v_turn, v_due, v_until;
  if v_turn is not null then
    return jsonb_build_object('queued', true, 'joined', true, 'turn_id', v_turn, 'due_at', v_due, 'standby_until', case when v_until > now() then v_until end, 'woke', v_woke);
  end if;
  -- «وضع الاستعداد»: the minutes to wait for a staff reply first (NULL = none — today's burst)
  v_wait := internal.hub_standby_minutes(c.id, p_message, v_kind);
  insert into public.hub_turns (conversation_id, unit_id, inbound_message_ids, first_inbound_id, kind, due_at, is_test, standby_until, standby_reason)
  values (c.id, c.unit_id, array[p_message], p_message, v_kind,
          case when v_wait is not null then now() + make_interval(mins => v_wait) else now() + make_interval(secs => v_burst / 1000.0) end, c.is_test,
          case when v_wait is not null then now() + make_interval(mins => v_wait) end,
          -- H9 fix 3: why it waited or not (shown in «المحادثات» and «المحاكي»)
          internal.hub_standby_reason(c.id, p_message, v_kind))
  on conflict do nothing
  returning id, due_at into v_turn, v_due;
  if v_turn is null then
    select t.id, t.due_at into v_turn, v_due from public.hub_turns t where t.first_inbound_id = p_message;
    return jsonb_build_object('queued', false, 'reason', 'duplicate', 'turn_id', v_turn);
  end if;
  return jsonb_build_object('queued', true, 'turn_id', v_turn, 'due_at', v_due, 'kind', v_kind, 'standby_until', case when v_wait is not null then v_due end);
end;
$$;

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  -- H11 (Ahmed, 24 Nov 2026 — «تم، أضفنا ذلك إلى طلبك.» twice in 5 seconds): the turns of one conversation one at a time —
  -- the conversation is locked BEFORE looking for a running turn, so a second claim waits for the first to commit and sees it
  perform 1 from public.hub_conversations where id = t.conversation_id for update;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  -- S1: a brand unit («السوشيال») answers for the conversation's branch once the guest named it (NULL until then)
  if u.kind = 'brand' then u.branch_slug := c.branch_slug; end if;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end,
                              -- «وضع الاستعداد»: no staff reply in the wait — the assistant answers after it
                              standby_outcome = case when standby_until is not null and standby_outcome is null and kind = 'reply'
                                                       and not (v_state = 'closed' or (v_state = 'human' and v_phase is null)) then 'assistant' else standby_outcome end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    -- H10 (bd27baf4 — three cards counted as three replies): the assistant's replies by TURN
    'replies_hour', (select count(distinct m.turn_id) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase, 'human_reason', c.human_reason,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test, 'branch', c.branch_slug, 'branch_pending', c.branch_pending),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled, 'kind', ch.kind, 'provider', ch.provider),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language,
      -- H8: a returning guest's previous room (a confirmed past stay on the same phone) — its card comes first
      'last_room', (select jsonb_build_object('branch', r.branch, 'room', rt.slug) from public.reservations r join public.room_types rt on rt.id = r.room_type_id
                     where r.phone = g.phone and r.status = 'confirmed' and not r.is_test and r.check_out <= internal.riyadh_today() order by r.check_out desc limit 1),
      -- H8: the «إياب» members' prices only for a member with recorded consent (applied by code, never inferred)
      'member', g.club_joined_at is not null and g.consent = 'granted',
      -- H8: «يُعامَل كضيف للتجربة» — a test reservation that never takes a room
      'test_guest', internal.hub_test_guest(g.phone)),
    -- H8: the live «إياب» members' codes of this branch, for a member only
    'member_codes', case when g.club_joined_at is not null and g.consent = 'granted' then
      (select coalesce(jsonb_agg(distinct o.promo_code), '[]'::jsonb) from public.offers o
        where o.audience = 'members' and o.category = 'individuals' and o.live is not null and o.archived_at is null and not o.is_test and o.promo_code is not null
          and (o.valid_to is null or o.valid_to >= internal.riyadh_today()) and (o.branches is null or cardinality(o.branches) = 0 or u.branch_slug is null or u.branch_slug = any (o.branches)))
      else '[]'::jsonb end,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript), 'kind', h.kind, 'at', h.sent_at) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H9: a departure check sent today and not answered yet — a typed answer («بمدد يومين», «طالع الساعة 11») is understood
    -- as «سأغادر في موعدي» / «أرغب في التمديد»; a late check-out question stays an ordinary question
    'departure', (select jsonb_build_object('id', d.id, 'ref', d.nazeel_ref) from public.hub_departures d
                   where d.phone = g.phone and d.branch_slug = u.branch_slug and d.answer is null and d.is_test = c.is_test
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and d.departure_date = internal.riyadh_today()
                   order by d.check_at desc limit 1),
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    -- H10: with the room, the party, breakfast and the recorded cancellation (a reply never contradicts it; the alternatives
    -- of a cancelled stay)
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out,
                                           'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'adults', r.adults, 'children', r.children,
                                           'breakfast', r.breakfast, 'cancel_reason_code', r.cancel_reason_code, 'cancelled_at', r.cancelled_at, 'source', r.booking_source)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and (r.is_test = c.is_test or (r.is_test and internal.hub_test_guest(g.phone)))
                          order by r.created_at desc limit 5) r),
    -- H10: every message we sent this guest outside the chat's text in the last 7 days — the booking templates (rendered by
    -- the engine with the variables they carried), the departure check, the review request, the arrival reminder; no phone
    'sent', (select coalesce(jsonb_agg(s.j order by s.at), '[]') from (
               select w.created_at as at, jsonb_build_object('at', w.created_at, 'template', w.template, 'meta_template', w.meta_template, 'language', w.language,
                        'status', w.status, 'ref', r.ref, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out, 'total', r.total,
                        'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'room_name_ar', r.room_name_ar, 'room_name_en', r.room_name_en,
                        'first_name', split_part(btrim(coalesce(r.guest_name, '')), ' ', 1), 'reason_code', coalesce(w.reason_code, r.cancel_reason_code)) as j
                 from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                where r.phone = g.phone and w.is_test = c.is_test and w.status not in ('failed', 'queued') and w.created_at > now() - interval '7 days'
               union all
               select e.created_at, jsonb_build_object('at', e.created_at, 'template', e.template, 'language', e.language, 'status', e.status)
                 from public.eyab_messages e
                where e.profile_id = g.id and e.is_test = c.is_test and e.status not in ('failed', 'queued') and e.created_at > now() - interval '3 days'
                  and e.template in ('stay_review', 'arrival_reminder', 'eyab_welcome', 'eyab_offer')
               union all
               select d.check_at, jsonb_build_object('at', d.check_at, 'template', 'stay_checkout_check', 'status', d.check_state)
                 from public.hub_departures d
                where d.phone = g.phone and d.is_test = c.is_test and d.check_at is not null and d.check_at > now() - interval '3 days'
                  and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test')
               order by 1 desc limit 8) s),
    -- H10: the hand-off notice ONCE per hand-off episode — whether it already went since the hand-off (no staff reply since),
    -- and whether «ما زال طلبك…» is due (30 minutes since our last message)
    'handoff', case when c.state = 'human' and c.owner_kind is null then jsonb_build_object(
                 'notice_open', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                          and m.created_at >= c.state_changed_at and m.status not in ('failed', 'rejected', 'superseded')
                                          and (coalesce((m.payload ->> 'notice')::boolean, false) or coalesce((m.payload ->> 'handoff')::boolean, false))),
                 'waiting_line_due', coalesce((select max(m.created_at) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                                and m.status not in ('failed', 'rejected', 'superseded')), c.state_changed_at) <= now() - interval '30 minutes')
               end,
    -- H10 (5fb7aac4): a staff or phone message of the last 3 hours asked about leaving or extending («خروج ولا تمديد؟»)
    'staff_departure_q', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.author in ('staff', 'phone')
                                   and m.created_at > now() - interval '3 hours' and coalesce(m.body, '') ~* '(خروج|تمديد|مغادر|تطلع|تغادر|تمدد|check ?out|extend|leaving)'),
    -- S1: a brand unit has no licences of its own — each topic takes the most restrictive of the active branch units'
    'licences', case when u.kind = 'brand' then
                  (select coalesce(jsonb_object_agg(z.topic_key, z.mode), '{}') from (
                     select l.topic_key, case when bool_or(l.mode = 'blocked') then 'blocked' when bool_or(l.mode = 'shadow') then 'shadow' else 'auto' end as mode
                       from public.hub_licences l join public.hub_units b on b.id = l.unit_id where b.kind = 'branch' and b.status = 'active' group by l.topic_key) z)
                else (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id) end,
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                           else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'show_prices'), false),
      -- H8: the branch's «الحجز الفوري» (off keeps the booking link as the fallback) and the instant limits (the reason texts)
      'instant_booking', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                               else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'instant_booking'), false),
      'limits', coalesce(internal.setting('instant_limits'), '{"same_day_cutoff": "20:00", "max_nights": 30}'::jsonb)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

create or replace function internal.hub_conv_team_after() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    update public.hub_handoffs set closed_at = coalesce(closed_at, now()) where id = old.handoff_id;
  end if;
  if new.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, is_test)
    -- S1: a brand unit's hand-off goes to the conversation's branch (Airport Road while none is known)
    select new.handoff_id, new.id, new.unit_id, coalesce(u.branch_slug, new.branch_slug, 'airport-road'), new.human_reason, new.is_test from public.hub_units u where u.id = new.unit_id
    on conflict do nothing;
    perform internal.hub_handoff_queue(new.handoff_id, 'alert');
  elsif new.handoff_id is not null and new.last_staff_at is not null and new.last_staff_at is distinct from old.last_staff_at then
    update public.hub_handoffs set first_reply_at = coalesce(first_reply_at, new.last_staff_at) where id = new.handoff_id;
  end if;
  return null;
end;
$$;

create or replace function internal.hub_test_lab_ready(u public.hub_units) returns boolean
language sql stable security definer set search_path = '' as $$
  select case when u.kind = 'brand' then coalesce((select bool_and(internal.hub_test_lab_ready(b)) and count(*) > 0
                                                    from public.hub_units b where b.kind = 'branch' and b.status = 'active'), false)
  else (internal.hub_unit_lab(u) ->> 'run_id') is not null and jsonb_array_length(coalesce(internal.hub_unit_lab(u) -> 'blocking', '[]'::jsonb)) = 0
     and coalesce((internal.hub_unit_lab(u) ->> 'items')::int, 0) > 0 end
$$;

create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and not h.extra and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      -- H10 (D1): the outcome of the chat bookings of the day, as they stand («4 (3 مؤكدة، 1 ملغاة)»)
      'bookings_confirmed', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'confirmed'),
      'bookings_cancelled', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'cancelled'),
      'bookings_waiting', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'request'),
      -- H11: the chat booking requests of the day left unconfirmed more than 15 minutes (the faults line)
      'requests_late', (select count(*) from public.hub_handoffs x where x.extra and x.reason = 'booking_request' and x.branch_slug = b and not x.is_test
                     and x.escalated_at is not null and x.created_at >= v_from and x.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to)
                 -- H9: and the review requests of «قائمة المغادرين»
                 + (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test
                      and d.review_state in ('accepted', 'sent', 'delivered', 'read') and d.review_at >= v_from and d.review_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      -- 15 Nov 2026: the staff alerts of the branch's hand-offs refused or failed (never silent)
      'staff_refused', (select count(*) from sends where sends.status in ('failed', 'skipped') and coalesce(sends.error_code, '') <> 'qa'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z),
      -- H9 «الخروج أو التمديد»: the day's departures of the list — the checks sent, «خروج», «تمديد», no answer
      'dep_on', exists (select 1 from public.hub_departure_config f where f.branch_slug = b and (f.check_on or f.review_on))
                or exists (select 1 from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_rows', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_sent', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_leave', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'leave'),
      'dep_extend', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'extend'),
      'dep_none', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer is null
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_dry', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.check_state = 'dry_run'),
      'dep_late', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state = 'skipped' and d.check_code in ('late', 'limit_late')),
      -- H9 fix 1: that day's morning list was not uploaded by 08:30 (a branch in use) — the 08:30 reminder's fault line
      'dep_missing', coalesce(p_to, now()) >= ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh'
                     and exists (select 1 from public.hub_departure_config f where f.branch_slug = b and f.remind_on)
                     and not exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and not x.is_test and x.departure_date = p_day
                                       and x.created_at < ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh')
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    -- the daily and test reports refused or failed (they belong to no hand-off)
    'reports_refused', (select count(*) from public.hub_staff_sends s where s.kind in ('report', 'report_test') and s.status in ('failed', 'skipped')
                          and coalesce(s.error_code, '') <> 'qa' and not s.is_test and s.created_at >= v_from and s.created_at < v_to),
    -- H7b: the cards published from the dashboard (the learned ones are listed below)
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.learn_kind is null and k.published_at >= v_from and k.published_at < v_to),
    -- H7b: the facts learned that day (teaching and staff replies), numbered for «امسح N» — still active; and what needs Ahmed's decision
    'learned', (select coalesce(jsonb_agg(jsonb_build_object('n', k.learn_no, 'short', coalesce(k.learn_short, k.title_ar), 'branch', k.learn_scope, 'kind', k.learn_kind,
                                                            'by', k.learn_by_name) order by k.learn_no), '[]'::jsonb)
                  from public.hub_knowledge_cards k where not k.is_test and k.learn_day = p_day and k.learn_no is not null and k.status <> 'archived' and k.learned_at <= v_to),
    'decisions', (select count(*) from public.hub_card_jobs j where not j.is_test and j.decision is not null and j.finished_at >= v_from and j.finished_at <= v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    -- H9: the sends held back by the shared limit that day (kept and tried again — never dropped silently)
    'limit_deferred', (select count(*) from public.whatsapp_messages w where not w.is_test and w.deferred_at >= v_from and w.deferred_at < v_to)
                    + (select count(*) from public.eyab_messages e where not e.is_test and e.deferred_at >= v_from and e.deferred_at < v_to)
                    + (select count(*) from public.hub_departures d where not d.is_test and ((d.check_deferred_at >= v_from and d.check_deferred_at < v_to)
                                                                                         or (d.review_deferred_at >= v_from and d.review_deferred_at < v_to))),
    -- S1 (25 Nov 2026): the day's conversations by channel («المحادثات: 34 (واتساب 25، انستجرام 6، ماسنجر 3)»)
    'channels', (select jsonb_build_object('whatsapp', count(*) filter (where z.kind = 'whatsapp'), 'instagram', count(*) filter (where z.kind = 'instagram'),
                                           'messenger', count(*) filter (where z.kind = 'messenger'), 'total', count(*))
                   from (select distinct c.id, ch.kind from public.hub_conversations c join public.hub_channels ch on ch.id = c.channel_id
                           join public.hub_messages m on m.conversation_id = c.id
                          where not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to) z),
    'built_at', now());
end;
$$;

create or replace function public.hub_thread(p_conversation uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  ch public.hub_channels;
  st jsonb;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or not internal.can_unit(c.unit_id, 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  st := internal.hub_assistant_state(u);
  return jsonb_build_object(
    'conversation', jsonb_build_object(
      'id', c.id, 'unit_id', u.id, 'unit_key', u.key, 'unit_kind', u.kind, 'branch', u.branch_slug,
      'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar),
      'channel_kind', ch.kind, 'channel_address', ch.address, 'sending_enabled', ch.sending_enabled,
      'state', c.state, 'state_before_human', c.state_before_human, 'test_state', c.test_state, 'owner_kind', c.owner_kind, 'owner_staff_id', c.owner_staff_id,
      'owner_name', internal.staff_name(c.owner_staff_id), 'human_reason', c.human_reason, 'priority', c.priority,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'waiting_since', c.waiting_since,
      -- S1: the conversation's branch on «السوشيال», and staff text with «Human Agent» (7 days) once Meta approved it
      'branch_named', c.branch_slug, 'channel_provider', ch.provider,
      'human_agent_until', case when ch.provider = 'meta' and (select x.meta_human_agent from public.hub_units x where x.id = ch.unit_id) then c.last_guest_at + interval '7 days' end,
      'last_guest_at', c.last_guest_at, 'last_staff_at', c.last_staff_at, 'tags', to_jsonb(c.tags), 'topics', to_jsonb(c.topics),
      'referral', c.referral, 'created_at', c.created_at, 'closed_at', c.closed_at, 'is_test', c.is_test,
      'can_edit', internal.can_unit(c.unit_id, 'edit'),
      'unit_mode', u.assistant_mode,
      'assistant', jsonb_build_object('active', (st ->> 'active')::boolean, 'mode', st ->> 'mode', 'reason', st ->> 'reason'),
      'can_release', internal.can_unit(c.unit_id, 'edit') and c.state = 'human' and (st ->> 'active')::boolean and st ->> 'mode' in ('shadow', 'licensed'),
      'can_pause', internal.can_unit(c.unit_id, 'edit') and u.assistant_mode <> 'off',
      -- «وضع الاستعداد»: the countdown «المساعد يرد بعد m:ss»
      'standby_until', internal.hub_standby_until(c.id),
      -- H9 fix 3: why the last turn waited or not («ينتظر رد الفريق» / «لم ينتظر: …»)
      'standby_last', internal.hub_standby_last(c.id),
      'templates_approved', (select coalesce(jsonb_agg(t.language order by t.language), '[]') from public.hub_templates t
                              where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.status = 'APPROVED')),
    'guest', jsonb_build_object(
      'id', g.id, 'name', g.name, 'wa_name', g.wa_profile_name, 'label', internal.hub_guest_label(g), 'phone', g.phone, 'language', g.language,
      'member', g.club_joined_at is not null, 'consent', g.consent, 'opted_out', g.wa_opt_out_at is not null, 'blocked', g.hub_blocked_at is not null,
      'marketing_hold', g.marketing_hold_at is not null, 'tags', to_jsonb(g.tags), 'notes', g.notes,
      'stays', (select count(*) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'last_stay', (select max(r.check_out) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                             order by r.check_in desc), '[]')
                     from (select * from public.reservations r where r.profile_id = g.id and internal.can_branch(r.branch) order by r.check_in desc limit 10) r)),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', m.id, 'direction', m.direction, 'author', m.author, 'staff_id', m.staff_id, 'staff_name', internal.staff_name(m.staff_id),
                   'kind', m.kind, 'body', m.body, 'payload', m.payload, 'language', m.language, 'media_path', m.media_path, 'media_mime', m.media_mime,
                   -- H7: «تفريغ صوتي» and the image's category
                   'transcript', m.transcript, 'transcript_seconds', m.transcript_seconds, 'media_category', m.media_category, 'media_status', m.media_status,
                   'media_purged', m.media_purged_at is not null or m.media_pending_delete, 'status', m.status, 'error_code', m.error_code,
                   'sent_at', m.sent_at, 'purged', m.purged_at is not null, 'unanswered', exists (select 1 from public.hub_unanswered q where q.message_id = m.id),
                   'translation', m.translation_ar, 'approved_by_name', internal.staff_name(m.approved_by), 'approved_at', m.approved_at,
                   'edited_before_send', m.edited_before_send, 'turn_id', m.turn_id,
                   'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', coalesce(k.live ->> 'title_ar', k.title_ar)) order by k.key), '[]')
                                 from public.hub_knowledge_cards k where k.id = any (m.source_card_ids)))
                   order by m.sent_at, m.created_at), '[]') from public.hub_messages m where m.conversation_id = c.id),
    'templates', (select coalesce(jsonb_agg(t order by t ->> 'at'), '[]') from (
                    select jsonb_build_object('source', 'booking', 'template', w.template, 'meta_template', w.meta_template, 'status', w.status, 'ref', w.ref,
                                              'branch', w.branch, 'language', w.language, 'at', w.created_at) t
                      from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                     where r.profile_id = g.id and internal.can_branch(r.branch) and w.status not in ('skipped')
                    union all
                    select jsonb_build_object('source', 'eyab', 'template', e.template, 'status', e.status, 'branch', e.branch, 'language', e.language, 'at', e.created_at)
                      from public.eyab_messages e where e.profile_id = g.id and e.status not in ('skipped') and internal.can_branch(e.branch)) s),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'reason', e.reason, 'at', e.at,
                                                           'actor', internal.staff_name(e.actor_staff_id)) order by e.at, e.id), '[]')
                 from public.hub_conversation_events e where e.conversation_id = c.id),
    'episodes', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'unit_name', xu.name_ar, 'state', x.state, 'created_at', x.created_at, 'closed_at', x.closed_at)
                                           order by x.created_at desc), '[]')
                   from public.hub_conversations x join public.hub_units xu on xu.id = x.unit_id
                  where x.guest_profile_id = g.id and x.id <> c.id and internal.can_unit(x.unit_id, 'view')),
    'transfer_units', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', coalesce(v.name_ar, t.name_ar)) order by t.sort), '[]')
                         from public.hub_units t left join public.dining_venues v on v.id = t.dining_venue_id where t.status = 'active' and t.id <> u.id),
    'team', (select coalesce(jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name) order by s.full_name), '[]')
               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id
               join public.staff_permissions sp on sp.user_id = s.user_id and sp.section = 'inbox' and sp.level >= 'edit'
              where m.unit_id = u.id and s.active),
    'timers', internal.hub_timers());
end;
$$;

create or replace function public.hub_book_draft(p_draft uuid, p_version integer, p_ref text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  d public.hub_drafts;
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  rt public.room_types;
  x public.reservations;
  f jsonb;
  q jsonb;
  v_test boolean;
  v_guest_test boolean;
  v_out jsonb;
  v_beds integer;
  v_adults integer;
  v_limit integer;
begin
  if p_ref is null or p_ref !~ '^AR-[0-9]{8}-[A-Z0-9]{4,8}$' then raise exception 'ref' using errcode = '22023'; end if;
  select * into d from public.hub_drafts where id = p_draft for update;
  if d.id is null then return jsonb_build_object('status', 'not_found'); end if;
  if d.reservation_id is not null then
    select * into x from public.reservations where id = d.reservation_id;
    return jsonb_build_object('status', 'already', 'id', x.id, 'ref', x.ref, 'booking_status', x.status, 'is_test', x.is_test);
  end if;
  if d.status <> 'open' or d.kind <> 'stay' or d.sim then return jsonb_build_object('status', 'stale', 'version', d.version); end if;
  if d.version <> p_version then return jsonb_build_object('status', 'stale', 'version', d.version); end if;
  select * into c from public.hub_conversations where id = d.conversation_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  f := d.fields;
  -- S1: on Instagram / Messenger the profile has no phone — the number the guest gave for the booking (copy.md §4.6)
  g.phone := coalesce(g.phone, case when f ->> 'phone' ~ '^\+[1-9][0-9]{7,14}$' then f ->> 'phone' end);
  q := d.quote -> 'chosen';
  if g.phone is null or g.hub_blocked_at is not null or coalesce(f ->> 'branch', '') = '' or coalesce(f ->> 'room_type', '') in ('', 'any')
     or coalesce(f ->> 'check_in', '') = '' or coalesce(f ->> 'check_out', '') = '' or coalesce(f ->> 'breakfast', '') not in ('with', 'without')
     or coalesce(btrim(f ->> 'guest_name'), '') = '' or q is null or coalesce(q ->> 'room', '') <> f ->> 'room_type' then
    return jsonb_build_object('status', 'incomplete');
  end if;
  select * into rt from public.room_types where branch = f ->> 'branch' and slug = f ->> 'room_type';
  if rt.id is null then return jsonb_build_object('status', 'not_bookable'); end if;
  v_test := c.is_test or d.is_test;
  v_guest_test := internal.hub_test_guest(g.phone);
  -- the website's per-phone limit (booking-request/limits.ts: 6 in 24 hours), on the assistant's own bookings
  v_limit := internal.hub_setting_int('hub_book_phone_day', 6);
  if not v_test and not v_guest_test and (select count(*) from public.reservations r where r.phone = g.phone and not r.is_test and r.created_at > now() - interval '24 hours') >= v_limit then
    return jsonb_build_object('status', 'limit');
  end if;
  v_adults := (f ->> 'adults')::int;
  v_beds := coalesce((q ->> 'extra_beds')::int, (f ->> 'extra_beds')::int, 0);
  if v_test or v_guest_test then perform set_config('app.hub_test_booking', 'on', true); end if;
  -- H10 (D1): every chat booking is a request
  perform set_config('app.hub_chat_request', 'on', true);
  begin
    v_out := public.submit_booking_sourced(jsonb_build_object(
      'ref', p_ref, 'branch', f ->> 'branch', 'room', f ->> 'room_type', 'check_in', f ->> 'check_in', 'check_out', f ->> 'check_out',
      'adults', v_adults, 'children', coalesce((f ->> 'children')::int, 0),
      'children_ages', case when jsonb_typeof(f -> 'child_ages') = 'array' then f -> 'child_ages' end,
      'extra_beds', v_beds, 'breakfast', f ->> 'breakfast', 'needs_coordination', v_adults > rt.capacity + v_beds, 'capacity', rt.capacity,
      'name', left(btrim(f ->> 'guest_name'), 120), 'phone', g.phone, 'locale', case when c.language = 'en' then 'en' else 'ar' end,
      'page', 'whatsapp', 'quoted_total', q ->> 'total', 'promo_code', nullif(q ->> 'promo_code', ''),
      'visit', jsonb_build_object('utm_source', 'whatsapp', 'utm_medium', 'chat'),
      'booking_source', 'assistant_whatsapp'));
    -- the quote said instant and the room went since (the website sold it first): nothing stored, the other rooms (T14)
    if v_out ->> 'status' = 'request' and coalesce((q ->> 'instant')::boolean, false) and v_out ->> 'reason' in ('sold_out', 'closed') then
      raise exception 'hub_sold_out' using errcode = 'P0H01';
    end if;
  exception
    when sqlstate 'P0H01' then
      perform set_config('app.hub_test_booking', '', true);
      perform set_config('app.hub_chat_request', '', true);
      return jsonb_build_object('status', 'sold_out');
    when sqlstate '22023' then
      perform set_config('app.hub_test_booking', '', true);
      perform set_config('app.hub_chat_request', '', true);
      return jsonb_build_object('status', 'not_bookable', 'reason', left(sqlerrm, 60));
  end;
  perform set_config('app.hub_test_booking', '', true);
      perform set_config('app.hub_chat_request', '', true);
  if v_out ->> 'status' = 'price_changed' then
    return jsonb_build_object('status', 'price_changed', 'new_total', (v_out -> 'quote' ->> 'total')::numeric, 'quote', v_out -> 'quote');
  end if;
  update public.hub_drafts set reservation_id = (v_out ->> 'id')::uuid, status = 'confirmed' where id = d.id;
  insert into public.hub_conversation_events (conversation_id, kind, to_value, reason, is_test)
  values (c.id, 'booking', v_out ->> 'status', v_out ->> 'reason', c.is_test);
  if not (v_test or v_guest_test) then
    insert into public.dashboard_signals (kind, branch, unit_id) values ('hub_booking', u.branch_slug, u.id);
  end if;
  -- H10 (D1): reception confirms the chat request — the slots on shift alerted now («تأكيد طلب حجز»), the branch's managers
  -- after 15 minutes still a request (hub_team_cron); never for a test reservation
  if v_out ->> 'status' = 'request' and not (v_test or v_guest_test) then
    perform internal.hub_extra_alert(c.id, 'booking_request', 'تأكيد طلب حجز', p_ref, false, (v_out ->> 'id')::uuid);
  end if;
  return v_out || jsonb_build_object('test', v_test, 'test_guest', v_guest_test, 'phone', g.phone, 'name', left(btrim(f ->> 'guest_name'), 120),
    'locale', case when c.language = 'en' then 'en' else 'ar' end, 'branch', f ->> 'branch', 'room_slug', rt.slug, 'room_name_ar', rt.name_ar, 'room_name_en', rt.name_en,
    'check_in', f ->> 'check_in', 'check_out', f ->> 'check_out', 'adults', v_adults, 'children', coalesce((f ->> 'children')::int, 0),
    'extra_beds', v_beds, 'breakfast', f ->> 'breakfast', 'capacity', rt.capacity, 'needs_coordination', v_adults > rt.capacity + v_beds);
end;
$$;

create or replace function internal.hub_standby_reason(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when p_kind <> 'reply' then 'tag'
    when exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id')) then 'tap'
    when u.kind = 'brand' and u.social_mode <> 'standby' then 'off'
    when u.kind <> 'brand' and (not coalesce(t.standby_on, false) or coalesce(t.standby_minutes, 0) not between 1 and 30) then 'off'
    when internal.hub_assistant_engaged(p_conversation) and internal.hub_exchange_open(p_conversation, p_message, p_at) then 'engaged'
    when not exists (select 1 from public.hub_staff_slots s where s.active and internal.hub_slot_covers(s, p_at)
                       and (s.branch_slug = u.branch_slug or (u.kind = 'brand' and (c.branch_slug is null or s.branch_slug = c.branch_slug)))) then 'no_shift'
    else 'waiting' end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation
$$;

create or replace function internal.hub_standby_minutes(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns integer
language sql stable security definer set search_path = '' as $$
  select case when internal.hub_standby_reason(p_conversation, p_message, p_kind, p_at) = 'waiting'
              then case when u.kind = 'brand' then u.social_standby_minutes::integer else t.standby_minutes end end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation
$$;
